 begin perform e10.normalize_market_screener_request(o,'catalog','variant','count','completed_sale','2026-01-01','2026-02-01','2026-02-01',null,'none',null,null,jsonb_build_object('manufacturer',repeat('x',66000)),'cohort_asc',50);raise exception'oversized filter payload accepted';exception when invalid_parameter_value then null;end;
